<script setup>import{ref,onMounted}from'vue';import api from'../services/api';const orders=ref([]);onMounted(async()=>{try{orders.value=(await api.get('/orders/mine')).data.orders||[]}catch{}})</script><template><section><h1 class="text-3xl font-black">My orders</h1><div class="mt-7 space-y-3"><div v-for="o in orders" :key="o.id" class="rounded-2xl border bg-white p-5"><div class="flex justify-between"><b>Order #{{o.id.slice(0,8)}}</b><span class="rounded-full bg-slate-100 px-3 py-1 text-xs font-bold">{{o.status}}</span></div><p class="mt-3 text-2xl font-black">{{Number(o.total).toLocaleString()}} {{o.currency}}</p><p class="text-sm text-slate-500">Payment: {{o.paymentStatus}}</p></div></div></section></template>